L21: // A session file's identity: resolved against `cwd` with symlinks resolved, a file that does not exist yet through its folder.
L22: // Synchronous, for an adapter that keys records by it; the core's own comparison is `canonicalPath`.
L23: export function sessionKey(file: string, cwd: string): string {
