L34: // Runs Kata without a shell, for an adapter whose host cannot put an environment on the call. Like pi.exec, a non-zero exit
L35: // or any spawn failure other than a missing executable is a result, a timeout or abort reports `killed`, and ENOENT rejects.
L36: export function execKata(file: string, args: string[], options: { cwd: string; timeout: number; env?: Record<string, string> }): Promise<Required<ExecResult>> {
L37: 	return new Promise((resolve, reject) => {
L38: 		execFile(file, args, { cwd: options.cwd, timeout: options.timeout, killSignal: "SIGKILL", maxBuffer: 64 * 1024 * 1024, env: { ...process.env, ...options.env } },
L39: 			(error, stdout, stderr) => {
L40: 				if (!error) return resolve({ code: 0, stdout, stderr, killed: false });
L41: 				const failure = error as NodeJS.ErrnoException & { killed?: boolean };
L42: 				if (failure.code === "ENOENT") return reject(error);
L43: 				resolve({ code: typeof failure.code === "number" ? failure.code : 1, stdout, stderr, killed: failure.name === "AbortError" || !!failure.killed });
L44: 			});
L45: 	});
L46: }
